function stopReading(){if('speechSynthesis' in window)speechSynthesis.cancel();}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopReading();});
const app=document.querySelector('#app');
const topics=[['Zahlenwerkstatt','Zahlenwörter & Stellenwerte','123','#e9edff','#364eb0'],['Zahlenstrahl','Schritt für Schritt zum Ziel','↔','#e0f3f4','#187079'],['Nachbarzahlen','Einer, Zehner, Hunderter','±','#fff0d4','#885812'],['Kopfrechnen','Malnehmen & Teilen','×','#fbe7ee','#a43d62'],['Rechenzauber','Klammern & Punkt vor Strich','( )','#efe8fc','#6d42a5'],['Geschichten','Mit Zahlen Rätsel lösen','?','#e5f2e8','#2e7649']];
let state={topic:0,level:0,index:0,stars:0,first:0,hints:0,tries:0,solved:false,paused:false,active:false,question:null};
const fmt=n=>new Intl.NumberFormat('de-DE').format(n).replaceAll('.',' ');
const pick=a=>a[Math.floor(Math.random()*a.length)];
const rand=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
const shuffle=a=>[...a].sort(()=>Math.random()-.5);
function home(){stopReading();state.active=false;app.innerHTML=`<section class="intro"><div><span class="eyebrow">DEINE KLEINE MATHE-AUSZEIT</span><h1>Was entdeckst du heute?</h1><p class="muted">Ein kleiner Schritt reicht. Du musst noch nicht alles können.</p></div><div class="badge"><b>✦ ${state.stars}</b><br>Sterne in dieser Sitzung</div></section><div class="layout"><section class="feature"><span class="pill">DEIN STARTPUNKT · 5 AUFGABEN</span><h2>Große Zahlen?<br>Wir machen sie klein.</h2><p>Baue Zahlen aus ihren Teilen zusammen.<br>Wir fangen ganz einfach an.</p><div class="example" aria-label="3 Tausender, 4 Hunderter, 4 Zehner, 2 Einer"><span><small>T</small>3</span><span><small>H</small>4</span><span><small>Z</small>4</span><span><small>E</small>2</span></div><button class="primary" data-start="0">Meine erste Runde starten</button></section><aside class="side"><h3>So geht deine Reise</h3><ol class="steps"><li><span class="stepnum">1</span>Eine Aufgabe auf einmal.</li><li><span class="stepnum">2</span>Ein Tipp, wenn du ihn brauchst.</li><li><span class="stepnum">3</span>Fünf Schritte. Dann eine Pause?</li></ol><p class="muted">Kein Countdown.<br>Du bestimmst das Tempo.</p></aside></div><div class="section-title"><h2>Oder wähle dein Abenteuer</h2><span class="muted">Klasse 4</span></div><section class="cards">${topics.map((t,i)=>`<button class="topic" data-start="${i}" style="--tint:${t[3]};--ink:${t[4]}"><span class="icon" aria-hidden="true">${t[2]}</span><strong>${t[0]}</strong><small>${t[1]}</small></button>`).join('')}</section><p class="footer-note">Fehler gehören zum Entdecken. Hilfe holen auch.</p>`;app.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(Number(b.dataset.start)));}
function start(topic){Object.assign(state,{topic,index:0,first:0,hints:0,tries:0,solved:false,paused:false,active:true});nextQuestion();}
function numberLine(start,step,target){let out=`<svg class="numberline" viewBox="0 0 650 112" role="img" aria-label="Zahlenstrahl von ${fmt(start)} bis ${fmt(start+10*step)} mit zehn gleich großen Abständen. Gesucht ist die Zahl am ${target}. Teilstrich nach dem Start."><line x1="35" x2="615" y1="45" y2="45" stroke="#66769d" stroke-width="3"/>`;for(let i=0;i<=10;i++){const x=35+i*58;out+=`<line x1="${x}" x2="${x}" y1="36" y2="55" stroke="#66769d" stroke-width="2"/>`;if(i===target)out+=`<circle cx="${x}" cy="45" r="13" fill="#2947bc"/><text x="${x}" y="25" text-anchor="middle" font-size="21" font-weight="bold" fill="#2947bc">?</text>`;if(i===0||i===10)out+=`<text x="${x}" y="87" text-anchor="middle" font-size="18" fill="#394a71">${fmt(start+i*step)}</text>`;}return out+'</svg>';}
function makeQuestion(t,hard,index){let q={title:'',prompt:'',answer:0,hints:[],explain:'',visual:'',choices:null};
if(t===0){const examples=hard?[[724038,'siebenhundertvierundzwanzigtausendachtunddreißig'],[902314,'neunhundertzweitausenddreihundertvierzehn'],[599003,'fünfhundertneunundneunzigtausenddrei'],[13400,'dreizehntausendvierhundert'],[30156,'dreißigtausendeinhundertsechsundfünfzig']]:[[3442,'dreitausendvierhundertzweiundvierzig'],[2036,'zweitausendsechsunddreißig'],[4105,'viertausendeinhundertfünf'],[6020,'sechstausendzwanzig'],[8009,'achttausendneun']];const [n,word]=examples[index%5];q.title=index%2?'Setze die Zahl zusammen.':'Wie schreibt man diese Zahl?';q.prompt=index%2?'Lies jede Stelle von links nach rechts.':word;q.answer=n;const digits=String(n).padStart(hard?6:4,'0').split('');const labels=hard?['HT','ZT','T','H','Z','E']:['T','H','Z','E'];q.visual=index%2?`<div class="place">${digits.map((d,i)=>`<div><small>${labels[i]}</small>${d}</div>`).join('')}</div>`:'';q.hints=[`Zerlege die Zahl: ${Math.floor(n/1000)} Tausender und ${n%1000} dazu.`,digits.map((d,i)=>`${labels[i]}: ${d}`).join(' · ')+' — Auch eine leere Stelle bekommt eine 0.'];q.explain=`${fmt(n)} = ${fmt(Math.floor(n/1000)*1000)} + ${n%1000}. Jede Ziffer hat ihren eigenen Platz.`;}
if(t===1){const step=hard?[1,1000,100,10,1000][index]:[1,10,100,10,100][index];const begin=hard?[49720,50000,89000,13800,70000][index]:[20,100,1000,300,2000][index];const target=rand(2,8);q.title='Welche Zahl steht beim Fragezeichen?';q.prompt='Finde zuerst die Größe eines Schrittes.';q.visual=numberLine(begin,step,target);q.answer=begin+step*target;q.hints=[`Von ${fmt(begin)} bis ${fmt(begin+10*step)} sind es ${fmt(step*10)}. Dazwischen liegen 10 gleich große Abstände.`,`Ein Schritt ist ${fmt(step)}. Gehe vom Start ${target} Schritte nach rechts.`];q.explain=`${fmt(begin)} + ${target} · ${fmt(step)} = ${fmt(q.answer)}. Zähle die Abstände, nicht den Startstrich.`;}
if(t===2){const units=[1,10,100,1000,10000],u=hard?units[index]:units[Math.min(index,3)];const n=hard?pick([13876,35341,25600]):pick([342,1260,2341]);const lower=index%2===0;const name={1:'Einer',10:'Zehner',100:'Hunderter',1000:'Tausender',10000:'Zehntausender'}[u];q.title=u===1?(lower?'Wie heißt der Vorgänger?':'Wie heißt der Nachfolger?'):`Welcher ${name} liegt direkt ${lower?'unter':'über'} der Zahl?`;q.prompt=fmt(n);q.answer=lower?Math.floor((n-1)/u)*u:(Math.floor(n/u)+1)*u;q.hints=[u===1?`Rechne ${lower?'minus':'plus'} 1.`:`Gesucht ist ein Vielfaches von ${fmt(u)}. Es endet auf ${String(u).length-1} Null${u===10?'':'en'}.`,`Die Zahl muss wirklich ${lower?'kleiner':'größer'} als ${fmt(n)} sein. ${u>1?'Gehe zum nächsten passenden vollen '+name+'.':''}`];q.explain=`${fmt(q.answer)} ist der ${lower?'vorherige':'nächste'} ${name} zu ${fmt(n)}.`;}
if(t===3){const a=rand(3,9),b=rand(3,9),factor=hard?10:1,divide=index%2===0;q.title=divide?'Teile in gleich große Gruppen.':'Wie viel ist das zusammen?';q.prompt=divide?`${a*b*factor} : ${b*factor}`:`${a} · ${b*factor}`;q.answer=divide?a:a*b*factor;q.hints=[divide?`Die Umkehraufgabe hilft: ${b*factor} · ? = ${a*b*factor}.`:`Rechne erst ${a} · ${b}.${factor===10?' Danach mal 10.':''}`,divide?`Wie oft passt ${b*factor} in ${a*b*factor}?`:`${a} · ${b} = ${a*b}.${factor===10?' Mit Zehnern wird daraus das Zehnfache.':''}`];q.explain=`${q.prompt} = ${fmt(q.answer)}.`;}
if(t===4){const sets=hard?[[ '4 · (120 + 80)',800,'120 + 80 = 200','4 · 200 = 800'],['(580 − 300) : 7',40,'580 − 300 = 280','280 : 7 = 40'],['(560 : 8) + 5',75,'560 : 8 = 70','70 + 5 = 75'],['4 · 60 − 5 · 30',90,'4 · 60 = 240 und 5 · 30 = 150','240 − 150 = 90'],['650 + 24 : 6',654,'24 : 6 = 4','650 + 4 = 654']]:[['3 · (10 + 5)',45,'10 + 5 = 15','3 · 15 = 45'],['(40 − 12) : 7',4,'40 − 12 = 28','28 : 7 = 4'],['(56 : 8) + 5',12,'56 : 8 = 7','7 + 5 = 12'],['4 · 6 − 5 · 3',9,'4 · 6 = 24 und 5 · 3 = 15','24 − 15 = 9'],['20 + 24 : 6',24,'24 : 6 = 4','20 + 4 = 24']];const [expr,n,first,last]=sets[index];q.title='Was rechnest du zuerst?';q.prompt=expr;q.answer=n;q.hints=['Erst die Klammer. Dann Mal und Geteilt. Dann Plus und Minus.',`Erster Schritt: ${first}. Jetzt fehlt noch eine Rechnung.`];q.explain=`${first}. Danach: ${last}.`;}
if(t===5){const a=hard?5:3,b=hard?10:4,c=index+2,d=hard?8:2;q.title='Das Fest im Zaubergarten';q.prompt=`Auf ${a} großen Tischen stehen jeweils ${b} Körbchen. Auf ${c} kleinen Tischen stehen jeweils ${d} Körbchen. Wie viele Körbchen sind es zusammen?`;q.answer=a*b+c*d;q.hints=[`Gesucht sind die Körbchen, nicht die Tische. Die großen Tische: ${a} · ${b} = ${a*b} Körbchen.`,`Die kleinen Tische: ${c} · ${d} = ${c*d} Körbchen. Zähle beide Ergebnisse zusammen.`];q.explain=`${a} · ${b} + ${c} · ${d} = ${q.answer}. Antwort: Es sind insgesamt ${q.answer} Körbchen.`;}
if(!hard&&t!==0&&t!==5){q.choices=shuffle([...new Set([q.answer,q.answer+pick([1,10]),Math.max(0,q.answer-pick([2,5])),q.answer+pick([3,20])])]);}return q;}
function nextQuestion(){stopReading();state.tries=0;state.hints=0;state.solved=false;state.question=makeQuestion(state.topic,state.level,state.index);renderQuestion();}
function renderQuestion(){const q=state.question;app.innerHTML=`<section class="exercise"><div class="toolbar"><button class="quiet" id="back">Themen</button><div class="dots" aria-label="${state.index} von 5 Aufgaben fertig">${Array.from({length:5},(_,i)=>`<span class="dot ${i<state.index?'done':''}"></span>`).join('')}</div><button class="quiet" id="pause">Pause</button></div><div class="level"><span>${topics[state.topic][0]}</span><label for="level">· Schwierigkeit</label><select id="level"><option value="0" ${!state.level?'selected':''}>Leicht einsteigen</option><option value="1" ${state.level?'selected':''}>Wie in der Schule</option></select></div><article class="paper"><span class="eyebrow">SCHRITT ${state.index+1} VON 5</span><h1 tabindex="-1" id="question-title">${q.title}</h1><div class="prompt ${state.topic===0||state.topic===5?'words':''}">${q.prompt}</div>${q.visual}<div id="answer-area">${q.choices?`<div class="answers">${q.choices.map(n=>`<button class="answer" data-answer="${n}">${fmt(n)}</button>`).join('')}</div>`:`<form id="answer-form" class="entry"><label for="answer">Deine Zahl${state.topic===5?' (Körbchen)':''}</label><input id="answer" inputmode="numeric" autocomplete="off" placeholder="z. B. 120" aria-describedby="feedback"><button class="primary">Prüfen</button></form>`}</div><div id="hint-area"></div><div id="feedback" role="status" aria-live="polite"></div><div class="actions"><button class="secondary" id="hint">Gib mir einen Tipp</button><button class="quiet" id="read">Vorlesen</button></div></article><p class="footer-note">Du darfst nachdenken, ausprobieren und Hilfe holen.</p></section>`;
document.querySelector('#back').onclick=home;document.querySelector('#pause').onclick=pause;document.querySelector('#level').onchange=e=>{state.level=Number(e.target.value);start(state.topic);};document.querySelector('#hint').onclick=hint;document.querySelector('#read').onclick=()=>{if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.resume();const msg=new SpeechSynthesisUtterance(q.title+' '+q.prompt.replaceAll('·',' mal ').replaceAll(':',' geteilt durch ').replaceAll('−',' minus '));msg.lang='de-DE';msg.rate=.85;const localVoice=speechSynthesis.getVoices().find(v=>v.localService&&v.lang.startsWith('de'));if(localVoice)msg.voice=localVoice;msg.onerror=()=>{const button=document.querySelector('#read');if(button)button.textContent='Vorlesen gerade nicht verfügbar';};speechSynthesis.speak(msg);}};if(!('speechSynthesis'in window))document.querySelector('#read').hidden=true;app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>check(b.dataset.answer));const form=document.querySelector('#answer-form');if(form)form.onsubmit=e=>{e.preventDefault();check(document.querySelector('#answer').value);};document.querySelector('#question-title').focus();}
function hint(){if(state.solved)return;const area=document.querySelector('#hint-area');if(state.hints<state.question.hints.length){area.insertAdjacentHTML('beforeend',`<div class="help">${state.question.hints[state.hints++]}</div>`);if(state.hints===state.question.hints.length)document.querySelector('#hint').textContent='Lösung gemeinsam ansehen';}else{finish(false);}}
function check(raw){if(state.solved||state.paused)return;const value=String(raw).trim();const valid=/^\d+$/.test(value)||/^\d{1,3}(?:[ .]\d{3})+$/.test(value);const s=valid?value.replaceAll(/[ .]/g,''):'';const fb=document.querySelector('#feedback');if(!/^\d+$/.test(s)){fb.className='feedback retry';fb.textContent='Trage eine ganze Zahl ein. Tausender darfst du mit einem Leerzeichen trennen.';return;}state.tries++;if(Number(s)===state.question.answer){finish(state.tries===1&&state.hints===0);}else{fb.className='feedback retry';fb.textContent='Noch nicht ganz. Schau dir den Tipp an und probiere es noch einmal.';if(state.hints<2)hint();}}
function finish(independent){state.solved=true;state.stars++;if(independent)state.first++;document.querySelector('#answer-area').querySelectorAll('button,input').forEach(b=>b.disabled=true);const fb=document.querySelector('#feedback');fb.className='feedback';fb.innerHTML=`<strong>${independent?'Genau! Du hast es herausgefunden.':'Ein Schritt geschafft – auch mit Hilfe zählt er.'} ✦</strong><br>${state.question.explain}`;document.querySelector('#hint').hidden=true;const btn=document.createElement('button');btn.className='primary';btn.textContent=state.index===4?'Runde abschließen':'Nächste Aufgabe';btn.onclick=()=>{state.index++;if(state.index===5)complete();else nextQuestion();};document.querySelector('.actions').prepend(btn);btn.focus();}
function complete(){state.active=false;app.innerHTML=`<section class="exercise paper center"><div class="bigstar" aria-hidden="true">✦ ✦ ✦</div><span class="eyebrow">DEINE RUNDE IST GESCHAFFT</span><h1>Fünf kleine Schritte weiter!</h1><p>Du hast dich mit ${topics[state.topic][0]} beschäftigt.<br>Das ist heute schon ein guter Anfang.</p><div class="summary"><div><b>5</b>Aufgaben bearbeitet</div><div><b>${state.first}</b>gleich ohne Hilfe gelöst</div></div><div class="help">Zeit für eine Pause? Steh auf, streck dich oder hol dir etwas zu trinken.</div><div class="actions" style="justify-content:center"><button class="primary" id="again">Noch eine Runde</button><button class="secondary" id="home">Zur Themenauswahl</button></div><p class="muted">Du darfst für heute auch fertig sein.</p></section>`;document.querySelector('#again').onclick=()=>start(state.topic);document.querySelector('#home').onclick=home;}
function pause(){state.paused=true;if('speechSynthesis'in window)speechSynthesis.cancel();const d=document.createElement('dialog');d.innerHTML='<h2>Deine Pause gehört dazu.</h2><p>Streck dich einmal groß. Schau aus dem Fenster. Oder trink einen Schluck Wasser.</p><p>Deine Aufgabe wartet auf dich.</p><button class="primary">Ich bin wieder da</button>';document.body.append(d);d.onclose=()=>{state.paused=false;d.remove();};d.querySelector('button').onclick=()=>d.close();d.showModal();}
document.querySelector('#parent').onclick=()=>document.querySelector('#info').showModal();home();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_math_round',description:'Startet sichtbar eine neue Runde mit fünf Aufgaben; ersetzt die laufende Runde.',inputSchema:{type:'object',properties:{topic:{type:'integer',minimum:0,maximum:5}},required:['topic'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Number.isInteger(input.topic)||input.topic<0||input.topic>5)throw new Error('Thema muss eine ganze Zahl von 0 bis 5 sein.');start(input.topic);return {topic:topics[state.topic][0],step:1,total:5};}})).catch(()=>{});}catch{}}
